# AI Office v2.5 Part F Intelligence Operations Live Validation Installer
$ErrorActionPreference = "Stop"
$Repository = "E:\AI\AI-Office"
if (-not (Test-Path -LiteralPath $Repository -PathType Container)) { throw "AI Office repository not found." }
Set-Location $Repository
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory = Join-Path $Repository ("workspace\installer-backups\v2.5-part-f-" + $Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force | Out-Null
foreach ($Directory in @("config\intelligence","scripts\intelligence","workspace\intelligence\live-validations","docs")) { New-Item -ItemType Directory -Path (Join-Path $Repository $Directory) -Force | Out-Null }
function Write-EmbeddedFile {
    param([string]$RelativePath,[string]$Base64Content)

    $Destination = Join-Path $Repository $RelativePath
    $Parent = Split-Path -Parent $Destination

    if ($Parent -and -not (Test-Path -LiteralPath $Parent)) {
        New-Item -ItemType Directory -Path $Parent -Force | Out-Null
    }

    if (Test-Path -LiteralPath $Destination -PathType Leaf) {
        $BackupPath = Join-Path $BackupDirectory $RelativePath
        $BackupParent = Split-Path -Parent $BackupPath

        if ($BackupParent -and -not (Test-Path -LiteralPath $BackupParent)) {
            New-Item -ItemType Directory -Path $BackupParent -Force | Out-Null
        }

        Copy-Item -LiteralPath $Destination -Destination $BackupPath -Force
    }

    [IO.File]::WriteAllBytes(
        $Destination,
        [Convert]::FromBase64String($Base64Content)
    )

    Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}
Write-EmbeddedFile -RelativePath "config\intelligence\operations-policy.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\intelligence\Get-AIOfficeIntelligenceOperationsStatus.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\intelligence\Show-AIOfficeIntelligenceOperations.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\intelligence\Invoke-AIOfficeLiveIntelligenceValidation.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\intelligence\Test-AIOfficeIntelligenceOperations.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v2.5-Part-F-Intelligence-Operations-Live-Validation.md" -Base64Content ""
$Scripts = Get-ChildItem "E:\AI\AI-Office\scripts\intelligence\*.ps1" -File
foreach ($Script in $Scripts) {
    $Tokens=$null; $ParseErrors=$null
    [System.Management.Automation.Language.Parser]::ParseFile($Script.FullName,[ref]$Tokens,[ref]$ParseErrors)|Out-Null
    if ($ParseErrors.Count -gt 0) { throw ("Syntax error in " + $Script.FullName + ": " + (($ParseErrors|ForEach-Object{$_.Message}) -join "; ")) }
}
Write-Host ""
Write-Host "AI Office v2.5 Part F Intelligence Operations and Live Validation installed successfully." -ForegroundColor Green
Write-Host "This part validates the live intelligence path without changing its routing policy." -ForegroundColor Cyan
Write-Host "Backups: $BackupDirectory" -ForegroundColor Cyan